:root {
  --radius: 0.625rem;
  --background: oklch(100% 0 0);
  --foreground: oklch(15% 0.05 295);
  --card: oklch(100% 0 0);
  --card-foreground: oklch(15% 0.05 295);
  --popover: oklch(100% 0 0);
  --popover-foreground: oklch(15% 0.05 295);
  --primary: oklch(45% 0.2 295);
  --primary-foreground: oklch(99% 0.005 295);
  --secondary: oklch(96.5% 0.015 295);
  --secondary-foreground: oklch(20% 0.05 295);
  --muted: oklch(96.5% 0.015 295);
  --muted-foreground: oklch(50% 0.05 295);
  --accent: oklch(96.5% 0.015 295);
  --accent-foreground: oklch(20% 0.05 295);
  /* Meets 4.5:1 against the translucent destructive status surfaces. */
  --destructive: oklch(50% 0.2 27.325);
  --destructive-foreground: oklch(99% 0.005 295);
  --success: oklch(49% 0.13 160);
  --success-foreground: oklch(47% 0.13 160);
  --warning: oklch(58% 0.14 75);
  --warning-foreground: oklch(44% 0.14 75);
  --border: oklch(92.5% 0.02 295);
  --input: oklch(92.5% 0.02 295);
  --ring: oklch(55% 0.15 295);
  --chart-1: oklch(0.646 0.222 41.116);
  --chart-2: oklch(0.6 0.118 184.704);
  --chart-3: oklch(0.398 0.07 227.392);
  --chart-4: oklch(0.828 0.189 84.429);
  --chart-5: oklch(0.769 0.188 70.08);
  --sidebar: oklch(98.5% 0.008 295);
  --sidebar-foreground: oklch(15% 0.05 295);
  --sidebar-primary: oklch(45% 0.2 295);
  --sidebar-primary-foreground: oklch(99% 0.005 295);
  --sidebar-accent: oklch(96.5% 0.015 295);
  --sidebar-accent-foreground: oklch(20% 0.05 295);
  --sidebar-border: oklch(92.5% 0.02 295);
  --sidebar-ring: oklch(55% 0.15 295);
  /*
   * Shared syntax palette for CodeMirror-backed controls. These colours retain
   * their semantic role on a white editor canvas and its active line at 4.5:1
   * contrast or higher.
   */
  --code-caret: #000000;
  --code-normal: var(--foreground);
  --code-comment: #626262;
  --code-function: #6f5700;
  --code-important: #9a4d00;
  --code-keyword: #a72a68;
  --code-operator: #b42318;
  --code-property: #007a78;
  --code-punctuation: var(--code-comment);
  --code-string: #087443;
  --code-tag: var(--code-operator);
  --code-value: #6245c2;
}

