:root {
  /* Typography */
  --ui-font-sans: "DM Sans Variable", sans-serif;
  --ui-font-mono: "Source Code Pro", monospace;
  --ui-font-size-xs: 0.75rem;
  --ui-font-size-sm: 0.875rem;
  --ui-font-size-md: 1rem;
  --ui-font-size-lg: 1.125rem;
  --ui-font-size-xl: 1.25rem;
  --ui-line-height-tight: 1.25;
  --ui-line-height-normal: 1.5;
  --ui-line-height-relaxed: 1.625;
  --ui-font-weight-regular: 400;
  --ui-font-weight-medium: 500;
  --ui-font-weight-semibold: 600;
  /* Spacing */
  --ui-space-0: 0;
  --ui-space-0-5: 0.125rem;
  --ui-space-1: 0.25rem;
  --ui-space-1-5: 0.375rem;
  --ui-space-2: 0.5rem;
  --ui-space-2-5: 0.625rem;
  --ui-space-3: 0.75rem;
  --ui-space-4: 1rem;
  --ui-space-5: 1.25rem;
  --ui-space-6: 1.5rem;
  --ui-space-8: 2rem;
  --ui-space-10: 2.5rem;
  --ui-space-12: 3rem;
  --ui-space-16: 4rem;
  /* Shape and elevation */
  --ui-radius-sm: calc(var(--radius, 0.5rem) - 0.25rem);
  --ui-radius-md: calc(var(--radius, 0.5rem) - 0.125rem);
  --ui-radius-lg: var(--radius, 0.5rem);
  --ui-radius-xl: calc(var(--radius, 0.5rem) + 0.25rem);
  --ui-radius-round: 9999px;
  --ui-shadow-xs: 0 1px 2px rgb(0 0 0 / 0.05);
  --ui-shadow-sm: 0 1px 3px rgb(0 0 0 / 0.1), 0 1px 2px rgb(0 0 0 / 0.06);
  --ui-shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.1),
    0 2px 4px -2px rgb(0 0 0 / 0.1);
  --ui-shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.1),
    0 4px 6px -4px rgb(0 0 0 / 0.1);
  /* Semantic color aliases */
  --ui-color-background: var(--background);
  --ui-color-foreground: var(--foreground);
  --ui-color-surface: var(--card);
  --ui-color-surface-foreground: var(--card-foreground);
  --ui-color-muted: var(--muted);
  --ui-color-muted-foreground: var(--muted-foreground);
  --ui-color-primary: var(--primary);
  --ui-color-primary-foreground: var(--primary-foreground);
  --ui-color-secondary: var(--secondary);
  --ui-color-secondary-foreground: var(--secondary-foreground);
  --ui-color-accent: var(--accent);
  --ui-color-accent-foreground: var(--accent-foreground);
  --ui-color-destructive: var(--destructive);
  --ui-color-destructive-foreground: var(--destructive-foreground);
  --ui-color-border: var(--border);
  --ui-color-input: var(--input);
  --ui-color-ring: var(--ring);
  /* Controls and focus */
  --ui-control-height-xs: 1.75rem;
  --ui-control-height-sm: 2rem;
  --ui-control-height-md: 2.25rem;
  --ui-control-height-lg: 2.5rem;
  --ui-icon-size-sm: 0.875rem;
  --ui-icon-size-md: 1rem;
  --ui-icon-size-lg: 1.25rem;
  --ui-focus-ring-width: 2px;
  --ui-focus-ring-offset: 2px;
  --ui-focus-ring-color: var(--ui-color-ring);
  /* Motion and layers */
  --ui-duration-fast: 120ms;
  --ui-duration-normal: 180ms;
  --ui-duration-slow: 260ms;
  --ui-ease-standard: cubic-bezier(0.2, 0, 0, 1);
  --ui-ease-emphasized: cubic-bezier(0.2, 0, 0, 1.2);
  --ui-layer-dropdown: 40;
  --ui-layer-sticky: 50;
  --ui-layer-dialog: 60;
  --ui-layer-toast: 70;
}

*,
::before,
::after {
  --ui-runtime-border-spacing-x: 0;
  --ui-runtime-border-spacing-y: 0;
  --ui-runtime-translate-x: 0;
  --ui-runtime-translate-y: 0;
  --ui-runtime-rotate: 0;
  --ui-runtime-skew-x: 0;
  --ui-runtime-skew-y: 0;
  --ui-runtime-scale-x: 1;
  --ui-runtime-scale-y: 1;
  --ui-runtime-ring-inset: initial;
  --ui-runtime-ring-offset-width: 0px;
  --ui-runtime-ring-offset-color: #fff;
  --ui-runtime-ring-color: rgb(59 130 246 / 0.5);
  --ui-runtime-ring-offset-shadow: 0 0 #0000;
  --ui-runtime-ring-shadow: 0 0 #0000;
  --ui-runtime-shadow: 0 0 #0000;
  --ui-runtime-shadow-colored: 0 0 #0000;
  --ui-runtime-blur: blur(0);
  --ui-runtime-brightness: brightness(1);
  --ui-runtime-contrast: contrast(1);
  --ui-runtime-grayscale: grayscale(0);
  --ui-runtime-hue-rotate: hue-rotate(0deg);
  --ui-runtime-invert: invert(0);
  --ui-runtime-saturate: saturate(1);
  --ui-runtime-sepia: sepia(0);
  --ui-runtime-drop-shadow: drop-shadow(0 0 #0000);
  --ui-runtime-backdrop-blur: blur(0);
  --ui-runtime-backdrop-brightness: brightness(1);
  --ui-runtime-backdrop-contrast: contrast(1);
  --ui-runtime-backdrop-grayscale: grayscale(0);
  --ui-runtime-backdrop-hue-rotate: hue-rotate(0deg);
  --ui-runtime-backdrop-invert: invert(0);
  --ui-runtime-backdrop-opacity: opacity(1);
  --ui-runtime-backdrop-saturate: saturate(1);
  --ui-runtime-backdrop-sepia: sepia(0);
}

:root {
  --ui-button-background: var(--ui-color-primary);
  --ui-button-foreground: var(--ui-color-primary-foreground);
  --ui-button-border-color: transparent;
  --ui-button-radius: var(--ui-radius-md);
  --ui-button-focus-ring-color: var(--ui-focus-ring-color);
  --ui-button-shadow: var(--ui-shadow-xs);
}

:where([data-ui-component="button"], .cn-button) {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  gap: var(--ui-space-2);
  border: 1px solid var(--ui-button-border-color);
  border-radius: var(--ui-button-radius);
  font-family: var(--ui-font-sans);
  font-size: var(--ui-font-size-sm);
  font-weight: var(--ui-font-weight-medium);
  line-height: var(--ui-line-height-tight);
  white-space: nowrap;
  text-decoration: none;
  cursor: pointer;
  transition:
    color var(--ui-duration-fast) var(--ui-ease-standard),
    background-color var(--ui-duration-fast) var(--ui-ease-standard),
    border-color var(--ui-duration-fast) var(--ui-ease-standard),
    box-shadow var(--ui-duration-fast) var(--ui-ease-standard);
}

:where([data-ui-component="button"], .cn-button):focus-visible {
  outline: none;
  box-shadow:
    0 0 0 var(--ui-focus-ring-offset) var(--ui-color-background),
    0 0 0 calc(var(--ui-focus-ring-offset) + var(--ui-focus-ring-width))
      var(--ui-button-focus-ring-color);
}

:where([data-ui-component="button"], .cn-button):disabled,
:where([data-ui-component="button"], .cn-button)[aria-disabled="true"] {
  pointer-events: none;
  opacity: 0.5;
}

:where([data-ui-component="button"], .cn-button) > svg {
  width: var(--ui-icon-size-md);
  height: var(--ui-icon-size-md);
  flex-shrink: 0;
  pointer-events: none;
}

:where(
    [data-ui-component="button"][data-variant="default"],
    .cn-button.cn-button--default
  ) {
  color: var(--ui-button-foreground);
  background: var(--ui-button-background);
  box-shadow: var(--ui-button-shadow);
}

:where(
    [data-ui-component="button"][data-variant="default"],
